<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {usePrivateState} from './private-state.js';
import {reportRegistry} from './report-registry.mjs';
import PrivateStateStatus from './PrivateStateStatus.vue';
import {AXES,REASON_CATEGORIES,SCENARIOS,INPUT_LABELS,emptyResearchWorkspace,validateResearchWorkspace,appendResearchRevision,calculateScenarioSet,evaluateManualRule,classifyPublication,previewManualImport,safeResearchUrl} from './research-workflow.mjs';
import './research-cycle.css';
const props=defineProps({company:{type:String,required:true},bundle:{type:Object,default:null},active:{type:Boolean,default:true},mode:{type:String,default:'monthly'}});
const privateState=usePrivateState();
const {state,loaded,loading,busy,error,message,storage,authRequired,scope,resetBase,beginEdit}=privateState;
const modes={monthly:'月度核對',model:'三情境試算',rules:'台股觀察規則'};
const domains={monthly:'reviews',model:'scenarios',rules:'rules'};
const tab=ref(Object.hasOwn(modes,props.mode)?props.mode:'monthly'),draft=ref(null),errors=ref([]),errorBox=ref(null),discardPrompt=ref(false),importText=ref(''),importPreview=ref(null),datasetText=ref(''),datasetError=ref('');
let pinnedBase=null,pendingAction=null,draftUrl='';
const now=()=>new Date().toISOString(),copy=x=>JSON.parse(JSON.stringify(x));
const workspace=computed(()=>state.value.research_workspace||emptyResearchWorkspace());
const records=computed(()=>workspace.value[domains[tab.value]].filter(r=>r.company===props.company).slice().reverse());
const reportOptions=computed(()=>Object.entries(reportRegistry).filter(([id,r])=>r.ticker===props.company||id===(props.bundle?.manifest?.bundle_id||props.bundle?._manifest?.bundle_id)));
const result=computed(()=>draft.value&&tab.value==='model'?calculateScenarioSet(draft.value):null);
const ruleResult=computed(()=>draft.value&&tab.value==='rules'?evaluateManualRule(draft.value):null);
const baselineReady=computed(()=>/^[a-f0-9]{64}$/.test(draft.value?.baseline.bundle_sha256||''));
const outcomeLabels={keep:'維持',increase:'信心提高',decrease:'信心降低',withdraw:'撤回',pending:'尚待資料'};
const publicationLabels={known_by_cutoff:'截止前可公開取得',later:'截止後公開（事後資料）',time_unconfirmed:'發布日已知；盤中先後待核',unknown:'發布時間未知'};
function pathLabel(path){return path?.replace(/^research_workspace\.(reviews|scenarios|rules)\.\d+\./,'')||'研究內容';}
function fieldError(key){return errors.value.find(e=>e.path?.includes(key))?.message||'';}
function requestAction(action){if(busy.value){message.value='正在保存研究；完成後再切換。';return;}if(draft.value){pendingAction=action;discardPrompt.value=true;return;}action();}
function discard(){draft.value=null;errors.value=[];resetBase();pinnedBase=null;discardPrompt.value=false;const action=pendingAction;pendingAction=null;action?.();}
function keepDraft(){discardPrompt.value=false;pendingAction=null;}
function selectTab(value){requestAction(()=>{tab.value=value;updateUrl();});}
function updateUrl(){if(!props.active)return;const p=new URLSearchParams(location.search);p.set('researchCycle',tab.value);history.replaceState(history.state,'',location.pathname+'?'+p);}
function baseline(){const requested=(props.bundle?.manifest?.bundle_id||props.bundle?._manifest?.bundle_id),id=reportRegistry[requested]?requested:reportOptions.value.slice().sort((a,b)=>Date.parse(a[1].created_at)-Date.parse(b[1].created_at)).at(-1)?.[0]||null,r=reportRegistry[id];return {report_id:id,report_sha256:r?.report_sha256||null,bundle_sha256:props.bundle?._manifest?.sha256||props.bundle?.manifest_sha256||props.bundle?.bundle_sha256||r?.bundle_sha256||'',month:now().slice(0,7),cutoff:now()};}
function input(unused=false){return {value:null,kind:'assumption',source:unused?'不適用（此營收公式未使用）':'',as_of:now(),reason:unused?'此營收公式未使用':'',missing_reason:unused?'此營收公式未使用':'尚未取得'};}
function scenario(){return {segments:[{name:'主要分部',method:'drivers',volume:input(),price:input(),base_revenue:input(true),growth:input(true)}],inputs:Object.fromEntries(Object.keys(INPUT_LABELS).map(k=>[k,input()])),tax_mode:'amount'};}
function start(){requestAction(()=>{resetBase();pinnedBase=beginEdit();draftUrl=location.href;const base={id:crypto.randomUUID(),company:props.company,supersedes:null,baseline:baseline(),created_at:now()};
 if(tab.value==='monthly')draft.value={...base,outcome:'pending',axes:Object.fromEntries(Object.keys(AXES).map(k=>[k,{baseline:'',new_evidence:[],support:'',counterevidence:'',unknown:''}])),evidence:[],reasons:[],counter_case:'',learning:'',tasks:[]};
 else if(tab.value==='model')draft.value={...base,horizon:'',currency:'TWD',amount_unit:'金額與股數使用相同倍數（例如：百萬元／百萬股）',share_basis:'稀釋加權平均股數；與EPS相同拆股基準',constraints:'',invalidation:'',cases:Object.fromEntries(Object.keys(SCENARIOS).map(k=>[k,scenario()]))};
 else {draft.value={...base,name:'',frozen_at:base.created_at,market:'TW',security:props.company,fundamental_confirmation:'',falsification:'',thresholds:{volume_ratio:2,price_change_pct:0,net_flow:0,relative_return_5d_pct:null},dataset:{rights:'public_metadata',rights_source:'',source_url:'',adjustment_basis:'unadjusted_no_actions',volume_unit:'shares',flow_unit:'shares',available_at:now(),calendar_source_url:'',calendar_verified:false,corporate_actions:[],benchmark:null,calendar:[],sessions:[],events:[]}};datasetText.value=JSON.stringify(draft.value.dataset,null,2);datasetError.value='';}
 errors.value=[];nextTick(()=>document.getElementById('cycle-form-title')?.focus());});}
function revise(record){requestAction(()=>{resetBase();pinnedBase=beginEdit();draftUrl=location.href;draft.value={...copy(record),id:crypto.randomUUID(),created_at:now(),supersedes:record.id};if(tab.value==='rules')datasetText.value=JSON.stringify(record.dataset,null,2);errors.value=[];});}
function chooseReport(){draft.value.baseline.report_id=draft.value.baseline.report_id||null;const r=reportRegistry[draft.value.baseline.report_id];draft.value.baseline.report_sha256=r?.report_sha256||null;if(!props.bundle)draft.value.baseline.bundle_sha256=r?.bundle_sha256||'';}
function addEvidence(){draft.value.evidence.push({id:crypto.randomUUID(),title:'',url:'',locator:'',published_at:now(),precision:'timestamp',rights:'link_only'});}
function removeEvidence(id){draft.value.evidence=draft.value.evidence.filter(e=>e.id!==id);for(const a of Object.values(draft.value.axes))a.new_evidence=a.new_evidence.filter(x=>x!==id);for(const r of draft.value.reasons)r.evidence_ids=r.evidence_ids.filter(x=>x!==id);}
function reasonChange(category,checked){draft.value.reasons=checked?[...draft.value.reasons,{category,note:'',evidence_ids:[]}]:draft.value.reasons.filter(r=>r.category!==category);}
function addTask(){draft.value.tasks.push({question:'',primary_source:'',completion_condition:'',deadline:null,deadline_reason:'尚待事件日期',priority:'',unfinished_reason:''});}
function inputChanged(i){i.value=i.value===''?null:Number(i.value);if(i.value===null){i.missing_reason||='尚未取得';}else i.missing_reason='';}
function addSegment(){for(const c of Object.values(draft.value.cases))c.segments.push({name:'新分部',method:'drivers',volume:input(),price:input(),base_revenue:input(true),growth:input(true)});}
function segmentChange(index,key,value){for(const c of Object.values(draft.value.cases)){c.segments[index][key]=value;if(key==='method'){const inactive=value==='drivers'?['base_revenue','growth']:['volume','price'],active=value==='drivers'?['volume','price']:['base_revenue','growth'];for(const field of inactive)if(c.segments[index][field].value===null)c.segments[index][field]=input(true);for(const field of active)if(c.segments[index][field].source.startsWith('不適用'))c.segments[index][field]=input();}}}
function parseDataset(){try{const data=JSON.parse(datasetText.value),candidate={...copy(draft.value),dataset:data},check=appendResearchRevision(workspace.value,'rules',candidate);if(!check.ok){datasetError.value=check.errors[0].message;return false;}draft.value.dataset=data;datasetError.value='';return true;}catch{datasetError.value='JSON格式錯誤；原候選仍保留。';return false;}}
async function showErrors(found){errors.value=found;await nextTick();document.querySelectorAll('.cycle-form details').forEach(el=>el.open=true);errorBox.value?.focus();}
async function save(){if(busy.value||!loaded.value||!draft.value||!baselineReady.value)return;if(tab.value==='rules'&&!parseDataset())return;const candidate={...copy(draft.value),created_at:now()},check=appendResearchRevision(workspace.value,domains[tab.value],candidate);if(!check.ok){await showErrors(check.errors);return;}const company=props.company,expectedScope=scope.value;const success=await privateState.save({...state.value,research_workspace:check.value},'研究版本已保存；原版仍可回查。如需更正，請另存修訂版。',pinnedBase);if(success&&scope.value===expectedScope&&props.company===company){draft.value=null;errors.value=[];pinnedBase=null;}}
async function recheckDraft(){if(await privateState.recheckDraft())pinnedBase=privateState.context();}
function previewImport(){importPreview.value=previewManualImport(importText.value);}
function beforeUnload(event){if(draft.value||busy.value){event.preventDefault();event.returnValue='';}}
function workspaceLeave(event){if(busy.value){event.preventDefault();message.value='正在保存研究；完成後再離開。';return;}if(!draft.value)return;if(!window.confirm('研究草稿尚未保存。確定放棄草稿並離開？')){event.preventDefault();return;}pendingAction=null;discard();}
watch(scope,(value,previous)=>{if(previous&&value!==previous){draft.value=null;importText.value='';importPreview.value=null;datasetText.value='';datasetError.value='';errors.value=[];pinnedBase=null;pendingAction=null;discardPrompt.value=false;}});
watch(()=>props.company,()=>{draft.value=null;resetBase();pinnedBase=null;errors.value=[];importPreview.value=null;importText.value='';datasetText.value='';datasetError.value='';pendingAction=null;discardPrompt.value=false;});
watch(()=>props.mode,value=>{if(Object.hasOwn(modes,value)&&!draft.value)tab.value=value;});
watch(()=>props.active,value=>{if(value){const requested=new URLSearchParams(location.search).get('researchCycle');if(Object.hasOwn(modes,requested)&&!draft.value)tab.value=requested;}});
function pop(){const requested=new URLSearchParams(location.search).get('researchCycle');if(props.active&&Object.hasOwn(modes,requested)&&requested!==tab.value)requestAction(()=>{tab.value=requested;});}
function guardHistory(event){
 if(!props.active||(!draft.value&&!busy.value)||!draftUrl)return;
 const destination=new URL(location.href),original=new URL(draftUrl),keys=['workspace','company','bundle','researchView','companyTab','financialView','period','asOf','callSection','financialTopic','comparePeriod','researchCycle'];
 if(destination.pathname===original.pathname&&keys.every(key=>destination.searchParams.get(key)===original.searchParams.get(key)))return;
 const leave=new Event('workspace-leave',{cancelable:true});workspaceLeave(leave);
 if(leave.defaultPrevented){history.pushState(history.state,'',draftUrl);event.stopImmediatePropagation();}
}
onMounted(()=>{pop();window.addEventListener('beforeunload',beforeUnload);window.addEventListener('workspace-leave',workspaceLeave);window.addEventListener('popstate',guardHistory,true);window.addEventListener('popstate',pop);});
onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('workspace-leave',workspaceLeave);window.removeEventListener('popstate',guardHistory,true);window.removeEventListener('popstate',pop);});
defineExpose({hasUnsavedChanges:computed(()=>!!draft.value),requestLeave:requestAction});
</script>

<template>
<section class="research-cycle" aria-label="人工研究核對">
 <div class="cycle-heading"><div><h2>研究核對</h2><p>對照原判斷與新證據，明確接受下一個版本。</p></div><button v-if="loaded" type="button" @click="start" :disabled="busy">新增{{ modes[tab] }}</button></div>
 <nav class="cycle-tabs" aria-label="研究核對內容"><button v-for="(label,key) in modes" :key="key" type="button" :aria-pressed="tab===key" :disabled="busy" @click="selectTab(key)">{{ label }}</button></nav>
 <PrivateStateStatus :loading="loading" :loaded="loaded" :error="error" :message="message" :storage="storage" :auth-required="authRequired" reload-label="載入最新後重新核對" @reload="recheckDraft"/>
 <div v-if="discardPrompt" class="cycle-notice" role="alertdialog" aria-label="尚有未保存研究"><p>目前草稿尚未保存。放棄後才能切換內容。</p><div class="cycle-actions"><button @click="keepDraft" autofocus>繼續編輯</button><button @click="discard">放棄草稿</button></div></div>
 <div v-if="errors.length" ref="errorBox" class="cycle-errors" tabindex="-1" role="alert"><h3>請先核對內容</h3><ul><li v-for="(e,i) in errors" :key="i"><a href="#cycle-form-title">{{ pathLabel(e.path) }}：{{ e.message }}</a></li></ul></div>
 <form v-if="draft && loaded" class="cycle-form" :inert="busy" novalidate @submit.prevent="save">
  <h3 id="cycle-form-title" tabindex="-1">{{ draft.supersedes?'另存修訂版':'新研究草稿' }} · {{ modes[tab] }}</h3>
  <p class="cycle-muted">{{ draft.supersedes?'固定基線沿用原版；更換基線請另建研究。':'先固定這次研究的資料範圍。' }}</p>
  <p v-if="!baselineReady" role="status" class="cycle-field-error">尚無可固定的資料包版本，草稿暫不能保存。請先匯入此公司的財報與法說資料包，或選擇附有資料包版本的已登錄報告；核對真實 SHA-256 後再保存。</p>
  <fieldset :disabled="busy || !!draft.supersedes" class="cycle-grid"><legend>當時基線</legend><label>月份<input v-model="draft.baseline.month" type="month" required/></label><label>資料截至（ISO含時區）<input v-model="draft.baseline.cutoff" required aria-describedby="cutoff-help"/><span id="cutoff-help">例如 2026-10-31T23:59:59+08:00</span></label><label>固定報告版本<select v-model="draft.baseline.report_id" @change="chooseReport"><option :value="null">無已接受正文，以資料包固定基線</option><option v-for="([id,r]) in reportOptions" :key="id" :value="id">{{ r.ticker }} · {{ r.revision }} · {{ r.created_at.slice(0,10) }}</option></select></label><details><summary>版本核對紀錄</summary><label v-if="draft.baseline.report_id">報告內容SHA-256<input v-model="draft.baseline.report_sha256" required pattern="[a-f0-9]{64}"/></label><label>資料包SHA-256<input v-model="draft.baseline.bundle_sha256" required pattern="[a-f0-9]{64}"/></label><p v-if="fieldError('baseline')" class="cycle-field-error">{{ fieldError('baseline') }}</p></details></fieldset>
  <template v-if="tab==='monthly'">
   <label>這次人工核對結果<select v-model="draft.outcome"><option v-for="(label,key) in outcomeLabels" :key="key" :value="key">{{ label }}</option></select></label>
   <section class="cycle-section"><h4>新證據</h4><p>發布時間決定當時可知／事後資料；取回時間不能代替發布時間。</p><article v-for="(e,index) in draft.evidence" :key="e.id" class="cycle-subform"><h5>引用 {{ index+1 }} · {{ publicationLabels[classifyPublication(e,draft.baseline.cutoff)] }}</h5><div class="cycle-grid"><label>來源標題<input v-model="e.title" required maxlength="500"/></label><label>原始來源網址<input v-model="e.url" required type="url"/></label><label>頁／段／時間定位<input v-model="e.locator" required/></label><label>發布時間精度<select v-model="e.precision" @change="e.published_at=e.precision==='unknown'?null:e.precision==='day'?now().slice(0,10):now()"><option value="timestamp">精確含時區</option><option value="day">只有日期</option><option value="unknown">未知</option></select></label><label v-if="e.precision!=='unknown'">公開時間<input v-model="e.published_at" :type="e.precision==='day'?'date':'text'" required/></label><label>展示權利<select v-model="e.rights"><option value="link_only">僅連結與自寫摘要</option><option value="quoted_allowed">已確認允許短引</option></select></label></div><button type="button" @click="removeEvidence(e.id)">移除引用 {{ index+1 }}</button></article><button type="button" @click="addEvidence" :disabled="draft.evidence.length>=100">新增引用</button><p v-if="fieldError('evidence')" class="cycle-field-error">{{ fieldError('evidence') }}</p></section>
   <fieldset v-for="(label,key) in AXES" :key="key" class="cycle-axis"><legend>{{ label }}</legend><label>固定原判斷<textarea v-model="draft.axes[key].baseline" :disabled="!!draft.supersedes" rows="2" required/></label><fieldset v-if="draft.evidence.length"><legend>本軸新證據</legend><label v-for="e in draft.evidence" :key="e.id" class="cycle-check"><input v-model="draft.axes[key].new_evidence" type="checkbox" :value="e.id"/>{{ e.title || '未命名引用' }} · {{ publicationLabels[classifyPublication(e,draft.baseline.cutoff)] }}</label></fieldset><div class="cycle-grid"><label>支持<textarea v-model="draft.axes[key].support" rows="2" required/></label><label>反證<textarea v-model="draft.axes[key].counterevidence" rows="2" required/></label><label>未知／資料缺口<textarea v-model="draft.axes[key].unknown" rows="2" required/></label></div><p v-if="fieldError('axes.'+key)" class="cycle-field-error">{{ fieldError('axes.'+key) }}</p></fieldset>
   <fieldset><legend>維持／改判原因（可複選）</legend><label v-for="(label,key) in REASON_CATEGORIES" :key="key" class="cycle-check"><input type="checkbox" :checked="draft.reasons.some(r=>r.category===key)" @change="reasonChange(key,$event.target.checked)"/>{{ label }}</label><div v-for="r in draft.reasons" :key="r.category" class="cycle-subform"><label>{{ REASON_CATEGORIES[r.category] }}的具體理由<textarea v-model="r.note" required rows="2"/></label><fieldset><legend>支持這項理由的引用</legend><label v-for="e in draft.evidence" :key="e.id" class="cycle-check"><input type="checkbox" v-model="r.evidence_ids" :value="e.id"/>{{ e.title || '未命名引用' }}</label></fieldset></div><p v-if="fieldError('reasons')" class="cycle-field-error">{{ fieldError('reasons') }}</p></fieldset>
   <label>最強反方／替代解釋<textarea v-model="draft.counter_case" rows="3" required/></label><label>遺漏、過度解讀與這次學到的事<textarea v-model="draft.learning" rows="3" required aria-describedby="learning-help"/></label><p id="learning-help">價格和損益不代替主張的證據；價格軸不自動改寫基本面。</p>
   <section class="cycle-section"><h4>下月研究工作</h4><p>{{ 5-draft.tasks.length }} 項未安排。只列必要工作；日期作紀錄，由你手動發起。</p><fieldset v-for="(t,index) in draft.tasks" :key="index"><legend>工作 {{ index+1 }}</legend><label>待確認的問題<textarea v-model="t.question" rows="2" required/></label><label>待查一手來源網址<input v-model="t.primary_source" type="url" required/></label><label>怎樣算完成<textarea v-model="t.completion_condition" rows="2" required/></label><div class="cycle-grid"><label>預期完成日期<input v-model="t.deadline" type="date" @change="t.deadline=t.deadline||null;t.deadline_reason=t.deadline?'':'尚待事件日期'"/></label><label v-if="!t.deadline">日期未知原因<input v-model="t.deadline_reason" required/></label></div><label>優先處理的理由<textarea v-model="t.priority" rows="2" required/></label><label>尚未完成的原因<textarea v-model="t.unfinished_reason" rows="2"/></label><button type="button" @click="draft.tasks.splice(index,1)">移除工作 {{ index+1 }}</button></fieldset><button type="button" @click="addTask" :disabled="draft.tasks.length>=5">新增工作</button><p v-if="fieldError('tasks')" class="cycle-field-error">{{ fieldError('tasks') }}</p></section>
  </template>
  <template v-else-if="tab==='model'">
   <div class="cycle-grid"><label>試算期間<input v-model="draft.horizon" required/></label><label>貨幣<input v-model="draft.currency" required pattern="[A-Z]{3}" maxlength="3"/></label><label>金額與股數單位<input v-model="draft.amount_unit" required/></label><label>股數／拆股口徑<input v-model="draft.share_basis" required/></label></div><label>需求、產品組合、資本投入的交互約束<textarea v-model="draft.constraints" rows="2" required/></label><label>什麼結果讓模型失效<textarea v-model="draft.invalidation" rows="2" required/></label>
   <p>三情境使用相同算式。數值皆須說明來源、公開／假設時點及理由；情境不代表機率，倍數是研究者假設。</p>
   <div class="cycle-case-grid"><fieldset v-for="(label,key) in SCENARIOS" :key="key"><legend>{{ label }}</legend><label>稅务處理<select v-model="draft.cases[key].tax_mode" @change="Object.values(draft.cases).forEach(c=>c.tax_mode=draft.cases[key].tax_mode)"><option value="amount">明確稅額（須來源／理由）</option><option value="rate_no_credit">稅率；虧損不假定稅益</option></select></label>
    <fieldset v-for="(s,index) in draft.cases[key].segments" :key="index"><legend>營收分部 {{ index+1 }}</legend><label>分部名稱<input :value="s.name" @input="segmentChange(index,'name',$event.target.value)" required/></label><label>營收公式<select :value="s.method" @change="segmentChange(index,'method',$event.target.value)"><option value="drivers">數量 × 單價</option><option value="growth">原營收 ×（1＋成長率）</option></select></label><div v-for="k in s.method==='drivers'?['volume','price']:['base_revenue','growth']" :key="k" class="cycle-input"><label>{{ {volume:'數量',price:'單價',base_revenue:'原營收',growth:'成長率（小數）'}[k] }}<input v-model="s[k].value" type="number" step="any" @input="inputChanged(s[k])"/></label><label v-if="s[k].value===null">缺值原因<input v-model="s[k].missing_reason" required/></label><details><summary>輸入依據</summary><label>類型<select v-model="s[k].kind"><option value="actual">已公開實際值</option><option value="assumption">研究者假設</option></select></label><label>來源／定位<input v-model="s[k].source" required/></label><label>公開／假設時間<input v-model="s[k].as_of" required/></label><label>採用理由<textarea v-model="s[k].reason" required rows="2"/></label></details></div></fieldset>
    <div v-for="(label,k) in INPUT_LABELS" :key="k" class="cycle-input"><label>{{ label }}<input v-model="draft.cases[key].inputs[k].value" type="number" step="any" @input="inputChanged(draft.cases[key].inputs[k])"/></label><label v-if="draft.cases[key].inputs[k].value===null">缺值原因<input v-model="draft.cases[key].inputs[k].missing_reason" required/></label><details><summary>輸入依據</summary><label>類型<select v-model="draft.cases[key].inputs[k].kind"><option value="actual">已公開實際值</option><option value="assumption">研究者假設</option></select></label><label>來源／定位<input v-model="draft.cases[key].inputs[k].source" required/></label><label>公開／假設時間<input v-model="draft.cases[key].inputs[k].as_of" required/></label><label>採用理由<textarea v-model="draft.cases[key].inputs[k].reason" required rows="2"/></label></details></div>
    <dl class="cycle-results"><div v-for="(label,k) in {revenue:'營收',gross_profit:'毛利',operating_income:'營業利益',pretax:'稅前利益',tax:'稅額',common_net_income:'普通股淨利',eps:'EPS',value_per_share:'條件每股價值'}" :key="k"><dt>{{ label }}</dt><dd>{{ result[key][k]===null?'無法計算':result[key][k].toLocaleString(undefined,{maximumFractionDigits:4}) }}</dd></div></dl><p>{{ result[key].valuation_reason }}</p><details v-if="result[key].missing.length"><summary>缺值與影響</summary><ul><li v-for="m in result[key].missing" :key="m.input">{{ m.input }}：{{ m.reason }}</li></ul></details>
   </fieldset></div><button type="button" @click="addSegment" :disabled="draft.cases.base.segments.length>=30">三情境新增相同分部</button><p v-if="fieldError('cases')" class="cycle-field-error">{{ fieldError('cases') }}</p><details><summary>計算核對紀錄</summary><p>營收＝分部數量×單價的總和，或分部原營收×（1＋成長率）。毛利＝營收×毛利率；營業利益＝毛利−營業費用；稅前利益＝營業利益＋其他淨收入；普通股淨利＝稅前利益−稅−非控制權益−特別股股利；EPS＝普通股淨利÷稀釋加權平均股數。正EPS才可乘假設本益比。</p></details>
  </template>
  <template v-else>
   <fieldset :disabled="!!draft.supersedes || busy"><legend>事先凍結的觀察規則</legend><div class="cycle-grid"><label>規則名稱<input v-model="draft.name" required/></label><label>台股代號<input v-model="draft.security" required/></label><label>凍結時間<input v-model="draft.frozen_at" required/></label><label>成交量／前20日中位數至少<input v-model.number="draft.thresholds.volume_ratio" type="number" step="any" required min="0.01"/></label><label>當日漲跌幅至少（%）<input v-model.number="draft.thresholds.price_change_pct" type="number" step="any" required/></label><label>五日相對指數報酬至少（%；選填）<input v-model="draft.thresholds.relative_return_5d_pct" type="number" step="any" @input="draft.thresholds.relative_return_5d_pct=$event.target.value===''?null:Number($event.target.value)"/></label><label>當日法人淨流量至少（依資料單位）<input v-model.number="draft.thresholds.net_flow" type="number" step="any" required/></label></div><label>須核對的基本面確認條件<textarea v-model="draft.fundamental_confirmation" rows="3" required/></label><label>怎樣推翻這項觀察<textarea v-model="draft.falsification" rows="3" required/></label></fieldset>
   <p>人工評估成交量、價格與法人淨流量；法人淨買不是持有餘額，也不判定「主力」。符合門檻只列待核候選。</p><details open><summary>人工資料與權利核對</summary><p>貼上有來源與可用時間的交易日曆、觀察窗及事件JSON。至少當日加前20個可交易session；停牌、缺件與復權口徑需明確記錄。</p><label>唯讀候選資料<textarea v-model="datasetText" rows="12" spellcheck="false" aria-describedby="dataset-help dataset-error"/></label><p id="dataset-help">先按「核對候選資料」查看結果，再明確保存規則。這裡不連接行情供應商。</p><button type="button" @click="parseDataset">核對候選資料</button><p v-if="datasetError" id="dataset-error" role="alert" class="cycle-field-error">{{ datasetError }}</p></details>
   <article class="cycle-result" aria-live="polite"><h4>{{ {not_comparable:'尚無可比資料',candidate:'待人工核對候選',not_matched:'未達門檻'}[ruleResult.status] }}</h4><p>{{ ruleResult.reason }}</p><dl v-if="ruleResult.status!=='not_comparable'" class="cycle-results"><div><dt>量比</dt><dd>{{ ruleResult.volume_ratio?.toFixed(2) }}</dd></div><div><dt>日漲跌幅</dt><dd>{{ ruleResult.price_change_pct?.toFixed(2) }}%</dd></div><div><dt>五日相對指數報酬</dt><dd>{{ ruleResult.relative_return_5d_pct===null?'未提供可比指數':ruleResult.relative_return_5d_pct?.toFixed(2)+'%' }}</dd></div><div><dt>法人淨流量占成交量</dt><dd>{{ ruleResult.flow_ratio===null?'單位不可比或成交量為零':(ruleResult.flow_ratio*100).toFixed(2)+'%' }}</dd></div><div><dt>法人淨流量</dt><dd>{{ ruleResult.net_flow }} {{ ruleResult.flow_unit }}</dd></div></dl><ul v-if="ruleResult.event_alignment.length"><li v-for="(e,i) in ruleResult.event_alignment" :key="i">{{ e.title }} → {{ e.session_date || '日曆尚無後續交易日，對齊待核' }}</li></ul></article>
  </template>
  <div class="cycle-actions"><button class="primary" :disabled="busy || !loaded || !baselineReady" type="submit">{{ busy?'保存中…':'明確接受並保存新版本' }}</button><button :disabled="busy" type="button" @click="requestAction(()=>{})">取消編輯</button></div>
 </form>
 <p v-if="loaded && !records.length && !draft" class="cycle-empty">尚無{{ modes[tab] }}。新增後可固定當時的報告、證據與判斷。</p>
 <article v-for="r in records" :key="r.id" class="cycle-saved"><h3>{{ r.name || (tab==='monthly'?r.baseline.month+' · '+outcomeLabels[r.outcome]:r.horizon+' · 三情境') }}</h3><p>{{ r.created_at }} · {{ r.supersedes?'修訂版本':'原始版本' }} · 資料截至 {{ r.baseline.cutoff }}</p><p v-if="tab==='monthly'">{{ r.learning }}</p><p v-else-if="tab==='model'">{{ r.invalidation }}</p><p v-else>{{ r.fundamental_confirmation }}</p><button type="button" @click="revise(r)" :disabled="busy">{{ tab==='rules'?'另存人工資料核對':'編輯並另存修訂版' }}</button><details><summary>回查完整版本與引用</summary><template v-if="tab==='monthly'"><section v-for="(label,key) in AXES" :key="key"><h4>{{ label }}</h4><p>原判斷：{{ r.axes[key].baseline }}</p><p>支持：{{ r.axes[key].support }}</p><p>反證：{{ r.axes[key].counterevidence }}</p><p>未知：{{ r.axes[key].unknown }}</p></section><p>最強反方：{{ r.counter_case }}</p><ul><li v-for="e in r.evidence" :key="e.id"><a :href="safeResearchUrl(e.url)" target="_blank" rel="noopener noreferrer">{{ e.title }} · {{ e.locator }}</a> · {{ publicationLabels[classifyPublication(e,r.baseline.cutoff)] }}</li></ul><ol><li v-for="(t,i) in r.tasks" :key="i">{{ t.question }} · {{ t.completion_condition }} · {{ t.deadline || t.deadline_reason }}<p>優先理由：{{ t.priority }}</p><a :href="safeResearchUrl(t.primary_source)" target="_blank" rel="noopener noreferrer">一手來源</a><p v-if="t.unfinished_reason">未完成：{{ t.unfinished_reason }}</p></li></ol></template><details><summary>版本檢查紀錄</summary><pre>{{ JSON.stringify(r,null,2) }}</pre></details></details></article>
 <details v-if="loaded" class="cycle-import"><summary>人工匯入候選（只預覽）</summary><p>核對JSON格式、欄位與權利後顯示候選。預覽不執行、不寫入、不修改已保存判斷。</p><label>候選研究工作區JSON<textarea v-model="importText" rows="8" spellcheck="false"/></label><button @click="previewImport" type="button">唯讀預覽候選</button><div v-if="importPreview" aria-live="polite"><template v-if="importPreview.ok"><p>格式核對通過：{{ importPreview.counts.reviews }} 月度核對、{{ importPreview.counts.scenarios }} 情境模型、{{ importPreview.counts.rules }} 規則。尚未保存。</p><details><summary>候選完整內容</summary><pre>{{ JSON.stringify(importPreview.candidate,null,2) }}</pre></details></template><p v-for="(e,i) in importPreview.errors||[]" :key="i" role="alert">{{ e.message }}</p></div></details>
</section>
</template>
